package gui;import model.*;import service.DietRecommendation;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.*;
public class WeeklyPlanPanel extends Theme.BackgroundPanel{private final MainApp app;private final JPanel list=new JPanel();public WeeklyPlanPanel(MainApp a){app=a;setOpaque(false);setLayout(new BorderLayout(12,12));setBorder(new EmptyBorder(22,28,18,28));add(Theme.title("7-DAY SMART PLAN 📅"),BorderLayout.NORTH);list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));add(Theme.transparentScrollPane(list),BorderLayout.CENTER);JButton back=Theme.secondaryButton("← More");back.addActionListener(e->app.showPanel(MainApp.MORE));add(back,BorderLayout.SOUTH);}public void setVisible(boolean v){super.setVisible(v);if(v)load();}    public void refresh() { load(); }

private void load(){list.removeAll();User u=app.getCurrentUser();if(u==null)return;for(Map.Entry<String,java.util.List<MealPlan>>e:new DietRecommendation().getWeeklyPlan(u).entrySet()){JPanel c=Theme.cardPanel(new BorderLayout());c.add(Theme.header(e.getKey()),BorderLayout.NORTH);StringBuilder s=new StringBuilder("<html>");for(MealPlan m:e.getValue())s.append(m.getMealType()).append(": ").append(m.getDescription()).append(" • ").append(m.getCalories()).append(" kcal<br>");s.append("</html>");c.add(Theme.bodyLabel(s.toString()),BorderLayout.CENTER);list.add(c);list.add(Box.createVerticalStrut(8));}list.revalidate();list.repaint();}}
